drop function if exists public.jfs_public_demo_recent_orders();
create or replace function public.jfs_public_demo_context() returns table(id uuid,tenant_code text,business_name text,whatsapp text,phone text,address text,city text,province text) language sql stable security definer set search_path=public,pg_temp as $$ select t.id,t.tenant_code,t.business_name,t.whatsapp,t.phone,t.address,t.city,t.province from public.tenants t where t.tenant_code='JFS-LAUNDRY-DEMO-001' limit 1; $$;
create or replace function public.jfs_public_demo_products() returns table(id uuid,name text,price numeric,is_active boolean) language sql stable security definer set search_path=public,pg_temp as $$ select p.id,p.name,p.price,p.is_active from public.products p join public.tenants t on t.id=p.tenant_id where t.tenant_code='JFS-LAUNDRY-DEMO-001' order by p.name; $$;
create or replace function public.jfs_public_demo_update_tenant(p_business_name text,p_whatsapp text,p_address text) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin update public.tenants set business_name=trim(p_business_name),whatsapp=regexp_replace(coalesce(p_whatsapp,''),'\\D','','g'),address=trim(coalesce(p_address,'')),updated_at=now() where tenant_code='JFS-LAUNDRY-DEMO-001'; return found; end; $$;
create or replace function public.jfs_public_demo_upsert_product(p_product_id uuid,p_name text,p_price numeric) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; v_tenant uuid; begin select id into v_tenant from public.tenants where tenant_code='JFS-LAUNDRY-DEMO-001'; if nullif(trim(p_name),'') is null or p_price is null or p_price<=0 then raise exception 'INVALID_PRODUCT'; end if; if p_product_id is null then insert into public.products(tenant_id,name,price,is_active) values(v_tenant,trim(p_name),p_price,true) returning id into v_id; else update public.products set name=trim(p_name),price=p_price,is_active=true,updated_at=now() where id=p_product_id and tenant_id=v_tenant returning id into v_id; if v_id is null then raise exception 'PRODUCT_NOT_FOUND'; end if; end if; return v_id; end; $$;
create or replace function public.jfs_public_demo_deactivate_product(p_product_id uuid) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin update public.products p set is_active=false,updated_at=now() from public.tenants t where p.id=p_product_id and p.tenant_id=t.id and t.tenant_code='JFS-LAUNDRY-DEMO-001'; return found; end; $$;
create or replace function public.jfs_public_demo_recent_orders() returns table(id uuid,external_id text,status text,total_amount numeric,payment_status text,notes text,created_at timestamptz) language sql stable security definer set search_path=public,pg_temp as $$ select o.id,o.external_id,o.status,o.total_amount,o.payment_status,o.notes,o.created_at from public.jfs_orders o join public.tenants t on t.id=o.tenant_id where t.tenant_code='JFS-LAUNDRY-DEMO-001' order by o.created_at desc limit 50; $$;
create or replace function public.jfs_public_demo_update_order(p_order_id uuid,p_status text default null,p_payment_status text default null) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin if p_status is not null and p_status not in ('pending','processing','ready','completed','cancelled') then raise exception 'INVALID_STATUS'; end if; if p_payment_status is not null and p_payment_status not in ('unpaid','pending','paid','failed','refunded') then raise exception 'INVALID_PAYMENT_STATUS'; end if; update public.jfs_orders o set status=coalesce(p_status,o.status),payment_status=coalesce(p_payment_status,o.payment_status),paid_at=case when p_payment_status='paid' then coalesce(o.paid_at,now()) when p_payment_status is not null and p_payment_status<>'paid' then null else o.paid_at end,updated_at=now() from public.tenants t where o.id=p_order_id and o.tenant_id=t.id and t.tenant_code='JFS-LAUNDRY-DEMO-001'; return found; end; $$;
revoke all on function public.jfs_public_demo_context() from public;
revoke all on function public.jfs_public_demo_products() from public;
revoke all on function public.jfs_public_demo_update_tenant(text,text,text) from public;
revoke all on function public.jfs_public_demo_upsert_product(uuid,text,numeric) from public;
revoke all on function public.jfs_public_demo_deactivate_product(uuid) from public;
revoke all on function public.jfs_public_demo_recent_orders() from public;
revoke all on function public.jfs_public_demo_update_order(uuid,text,text) from public;
grant execute on function public.jfs_public_demo_context() to anon,authenticated;
grant execute on function public.jfs_public_demo_products() to anon,authenticated;
grant execute on function public.jfs_public_demo_update_tenant(text,text,text) to anon,authenticated;
grant execute on function public.jfs_public_demo_upsert_product(uuid,text,numeric) to anon,authenticated;
grant execute on function public.jfs_public_demo_deactivate_product(uuid) to anon,authenticated;
grant execute on function public.jfs_public_demo_recent_orders() to anon,authenticated;
grant execute on function public.jfs_public_demo_update_order(uuid,text,text) to anon,authenticated;
